export const pollTypes={single:'Opción única',multiple:'Selección múltiple',scale:'Escala de 1 a 5',text:'Respuesta abierta'};
export const pollTopics=['Política','Economía','Seguridad','Salud','Deportes','Vida cotidiana','Otros'];
export const pollClosed=(p,now=Date.now())=>p.closed||p.archived||new Date(p.closes_at).getTime()<=now;
export const percent=(n,total)=>total?Math.round(n/total*100):0;
export function pollInput(form){
 const kind=form.kind,title=form.title.trim(),description=form.description.trim(),options=kind==='scale'?['1 · Muy bajo','2 · Bajo','3 · Intermedio','4 · Alto','5 · Muy alto']:kind==='text'?[]:form.options.split('\n').map(s=>s.trim()).filter(Boolean);
 if(title.length<8||title.length>240)throw Error('Escribe una pregunta de 8 a 240 caracteres.');
 if(!pollTypes[kind]||!pollTopics.includes(form.topic))throw Error('Selecciona un formato y un tema.');
 if(['single','multiple'].includes(kind)&&(options.length<2||options.length>8||new Set(options.map(x=>x.toLowerCase())).size!==options.length||options.some(x=>x.length>120)))throw Error('Incluye entre 2 y 8 opciones distintas, una por línea, de hasta 120 caracteres.');
 const closes=new Date(form.closes);if(!Number.isFinite(+closes)||+closes<=Date.now()||+closes>Date.now()+366*86400000)throw Error('Elige un cierre futuro dentro de un año.');
 return {p_title:title,p_description:description,p_topic:form.topic,p_kind:kind,p_options:options,p_closes_at:closes.toISOString()};
}
export const questionsOf=p=>p.questions?.length?p.questions:[{title:p.title,kind:p.kind,options:p.options}];
export const answersOf=v=>v.answers||[{choices:v.choices,answer:v.answer}];
export function surveyInput(form,questions){
 if(!questions.length||questions.length>20)throw Error('Incluye entre 1 y 20 preguntas.');
 const normalized=questions.map((q,i)=>{try{const v=pollInput({...form,...q,description:'',options:q.options||''});return {title:v.p_title,kind:v.p_kind,options:v.p_options};}catch(e){throw Error(`Pregunta ${i+1}: ${e.message}`);}});
 const meta=pollInput({...form,kind:'text',options:''});
 if(meta.p_description.length>1500)throw Error('El contexto admite hasta 1500 caracteres.');
 return {p_title:meta.p_title,p_description:meta.p_description,p_topic:meta.p_topic,p_closes_at:meta.p_closes_at,p_questions:normalized};
}
export function surveyAnswers(p,data){
 return questionsOf(p).map((q,i)=>{const choices=data.getAll(`choice-${i}`).map(Number),answer=String(data.get(`answer-${i}`)||'').trim();
  if(q.kind==='text'?(answer.length<2||answer.length>1000):(!choices.length||(q.kind!=='multiple'&&choices.length!==1)||choices.some(n=>!Number.isInteger(n)||n<0||n>=q.options.length)||new Set(choices).size!==choices.length))throw Error(`Revisa tu respuesta a la pregunta ${i+1}.`);
  return {choices,answer};
 });
}
export function initTrends({db,esc,date,login}){
 const root=document.getElementById('tendencias');let user=null,rows=[],mode='all',topic='Todo',query='',limit=50,listVersion=0,detailVersion=0,current=null,ownVote=null,result=null;
 const $=id=>document.getElementById(id);
 root.innerHTML=`<div class="heading trends-heading"><div><span class="eyebrow">OPINIÓN / COMUNIDAD</span><h1>¿Qué estamos pensando?</h1><p>Participa y descubre cómo cambia la opinión de la comunidad.</p></div><button class="primary" id="new-poll">＋ Crear encuesta</button></div><div class="trends-tabs" role="group" aria-label="Vistas de encuestas"><button data-poll-mode="all" class="active" aria-pressed="true">Explorar</button><button data-poll-mode="mine" aria-pressed="false">Mis encuestas</button><button data-poll-mode="results" aria-pressed="false">Resultados</button></div><div class="trends-tools"><label>Buscar encuestas<input type="search" id="poll-search" placeholder="Pregunta o tema"></label><button id="refresh-polls">↻ Actualizar</button></div><div class="topic-chips" id="poll-topics" role="group" aria-label="Temas de encuestas">${['Todo',...pollTopics].map(t=>`<button data-poll-topic="${t}" class="${t==='Todo'?'active':''}" aria-pressed="${t==='Todo'}">${t}</button>`).join('')}</div><p id="poll-status" role="status"></p><div class="trends-layout"><div><div id="poll-list"></div><button id="more-polls" hidden>Ver más encuestas</button></div><aside class="trends-aside"><section class="panel"><span class="eyebrow">TU VOZ CUENTA</span><h2>Una pregunta abre una conversación.</h2><p>Crea una encuesta, participa y consulta sus resultados reales.</p><button id="trends-login">Mi cuenta de Convergencia</button></section><section class="panel"><h2>Cómo leer los resultados</h2><p>Participación voluntaria. Los porcentajes describen a quienes responden, no representan a toda la población.</p><p>Una respuesta por cuenta. Las preguntas publicadas no se modifican para mantener comparables las respuestas.</p><p>En selección múltiple, los porcentajes pueden sumar más de 100%.</p><p class="muted">Cada encuesta muestra su periodo, número de participantes y formato. No se aplica ponderación ni se informa margen de error.</p></section></aside></div>`;
 const create=document.createElement('dialog');create.id='poll-create';create.className='poll-dialog';create.setAttribute('aria-labelledby','poll-create-title');create.innerHTML=`<button class="close" aria-label="Cerrar creación de encuesta">×</button><span class="eyebrow">TENDENCIAS / NUEVA ENCUESTA</span><h2 id="poll-create-title">¿Qué quieres preguntar?</h2><form id="poll-create-form"><label>Título de la encuesta<input name="title" required minlength="8" maxlength="240" placeholder="Ej. ¿Qué mejora necesita tu barrio?"></label><label>Contexto y objetivo<textarea name="description" maxlength="1500" placeholder="Explica para qué se utilizarán las respuestas, sin orientar la respuesta."></textarea></label><label>Tema<select name="topic">${pollTopics.map(t=>`<option>${t}</option>`).join('')}</select></label><div class="survey-builder-heading"><h3>Preguntas</h3><span id="question-count"></span></div><p class="muted">Combina hasta 20 preguntas. Todas se responden antes de enviar.</p><div id="survey-questions"></div><button type="button" id="add-question">＋ Agregar pregunta</button><label>Cierre de la encuesta<input name="closes" type="datetime-local" required></label><p class="muted">La pregunta, el contexto y las opciones serán públicos. Las respuestas abiertas se mostrarán sin el nombre de la cuenta. No solicites datos personales.</p><button class="primary" id="publish-poll">Publicar encuesta</button><p id="poll-create-status" role="status"></p></form>`;document.body.append(create);
 const detail=document.createElement('dialog');detail.id='poll-detail';detail.className='poll-dialog';detail.setAttribute('aria-labelledby','poll-detail-title');detail.innerHTML='<button class="close" aria-label="Cerrar encuesta">×</button><div id="poll-detail-body"></div>';document.body.append(detail);
 create.querySelector('.close').onclick=()=>create.close();detail.querySelector('.close').onclick=()=>detail.close();detail.addEventListener('close',()=>{detailVersion++;});
 function requireUser(){if(user)return true;login();return false;}
 $('new-poll').onclick=()=>{if(!requireUser())return;if(!create.querySelector('[name=closes]').value){const d=new Date(Date.now()+7*86400000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());create.querySelector('[name=closes]').value=d.toISOString().slice(0,16);}create.showModal();};
 $('trends-login').onclick=login;
 const form=$('poll-create-form');let questionSerial=0;
 function updateQuestions(){const cards=[...$('survey-questions').children];$('question-count').textContent=`${cards.length} de 20`;cards.forEach((card,i)=>{card.querySelector('legend').textContent=`Pregunta ${i+1}`;card.querySelector('[data-remove]').disabled=cards.length===1;card.querySelector('[data-up]').disabled=i===0;card.querySelector('[data-down]').disabled=i===cards.length-1;});$('add-question').disabled=cards.length>=20;}
 function addQuestion(){if($('survey-questions').children.length>=20)return;const card=document.createElement('fieldset'),id=++questionSerial;card.className='survey-question-editor';card.innerHTML=`<legend></legend><label for="question-title-${id}">Texto de la pregunta</label><input id="question-title-${id}" data-title required minlength="8" maxlength="240" placeholder="¿Qué quieres conocer?"><label for="question-kind-${id}">Formato</label><select id="question-kind-${id}" data-kind>${Object.entries(pollTypes).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><div data-options-wrap><label for="question-options-${id}">Opciones · una por línea</label><textarea id="question-options-${id}" data-options rows="3" placeholder="Primera opción&#10;Segunda opción"></textarea></div><p data-scale class="muted" hidden>1 · Muy bajo a 5 · Muy alto. Formula la pregunta para esta escala.</p><div class="question-tools"><button type="button" data-up aria-label="Subir pregunta">↑ Subir</button><button type="button" data-down aria-label="Bajar pregunta">↓ Bajar</button><button type="button" data-remove>Quitar pregunta</button></div>`;
 card.querySelector('[data-kind]').onchange=e=>{card.querySelector('[data-options-wrap]').hidden=!['single','multiple'].includes(e.target.value);card.querySelector('[data-scale]').hidden=e.target.value!=='scale';};
 card.querySelector('[data-remove]').onclick=()=>{card.remove();updateQuestions();};card.querySelector('[data-up]').onclick=()=>{if(card.previousElementSibling)card.previousElementSibling.before(card);updateQuestions();};card.querySelector('[data-down]').onclick=()=>{if(card.nextElementSibling)card.nextElementSibling.after(card);updateQuestions();};$('survey-questions').append(card);updateQuestions();return card;}
 function resetBuilder(){form.reset();$('survey-questions').replaceChildren();addQuestion();$('poll-create-status').textContent='';}
 $('add-question').onclick=()=>addQuestion()?.querySelector('[data-title]').focus();resetBuilder();
 form.onsubmit=async e=>{e.preventDefault();if(!user)return;const uid=user.id;$('publish-poll').disabled=true;try{const questions=[...$('survey-questions').children].map(c=>({title:c.querySelector('[data-title]').value,kind:c.querySelector('[data-kind]').value,options:c.querySelector('[data-options]').value}));const input=surveyInput(Object.fromEntries(new FormData(form)),questions);const {data,error}=await db.rpc('atlas_dev_create_survey',input);if(error)throw error;if(user?.id!==uid)return;resetBuilder();create.close();await load();const p=rows.find(p=>p.id===data);if(p)open(p);$('poll-status').textContent='Encuesta publicada en tu cuenta.';}catch(e){$('poll-create-status').textContent=e.message||'No se pudo publicar. Tu borrador se conserva.';}finally{$('publish-poll').disabled=false;}};
 root.querySelectorAll('[data-poll-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.pollMode;root.querySelectorAll('[data-poll-mode]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});render();});
 root.querySelectorAll('[data-poll-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.pollTopic;root.querySelectorAll('[data-poll-topic]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});render();});
 $('poll-search').oninput=e=>{query=e.target.value;render();};$('refresh-polls').onclick=load;$('more-polls').onclick=()=>{limit+=50;load();};
 function render(){
  const filtered=rows.filter(p=>(mode==='mine'?p.owner_id===user?.id:!p.archived)&&(topic==='Todo'||p.topic===topic)&&`${p.title} ${p.description}`.toLocaleLowerCase().includes(query.toLocaleLowerCase()));
  $('poll-list').innerHTML=filtered.map((p,i)=>`<article class="poll-card ${i===0?'featured':''}"><div class="poll-meta"><span class="poll-badge ${pollClosed(p)?'ended':''}">${p.archived?'ARCHIVADA':pollClosed(p)?'CERRADA':'ABIERTA'}</span><span>${esc(p.topic)} · ${questionsOf(p).length>1?`${questionsOf(p).length} preguntas · formatos combinados`:esc(pollTypes[questionsOf(p)[0].kind])}</span></div><h2>${esc(p.title)}</h2>${p.description?`<p>${esc(p.description)}</p>`:''}${i===0&&mode!=='results'&&questionsOf(p).length===1&&p.options.length?`<div class="poll-preview">${p.options.slice(0,5).map(o=>`<div><span aria-hidden="true">○</span>${esc(o)}</div>`).join('')}</div>`:''}<p class="muted">Cierre: ${esc(date(p.closes_at))}</p><div class="poll-actions"><button class="${i===0?'primary':''}" data-open-poll="${p.id}">${mode==='results'||pollClosed(p)?'Ver resultados':'Participar →'}</button><button data-result-poll="${p.id}">Resultados</button></div></article>`).join('')||`<div class="empty"><h2>${mode==='mine'&&!user?'Tus encuestas, en tu cuenta':rows.length?'No hay encuestas con estos filtros':'La primera pregunta puede ser tuya.'}</h2><p>${mode==='mine'&&!user?'Ingresa con Convergencia para crear y consultar tus encuestas.':'Crea una encuesta o explora otro tema. Los resultados aparecerán con las respuestas reales.'}</p></div>`;
  $('poll-list').querySelectorAll('[data-open-poll]').forEach(b=>b.onclick=()=>open(rows.find(p=>p.id===b.dataset.openPoll),mode==='results'));
  $('poll-list').querySelectorAll('[data-result-poll]').forEach(b=>b.onclick=()=>open(rows.find(p=>p.id===b.dataset.resultPoll),true));
 }
 async function load(){const v=++listVersion;$('poll-status').textContent='Cargando encuestas…';if(!db){$('poll-status').textContent='No se pudo conectar con Convergencia.';return;}try{const {data,error}=await db.from('atlas_dev_polls').select('*').order('created_at',{ascending:false}).limit(limit);if(error)throw error;if(v!==listVersion)return;rows=data;$('more-polls').hidden=data.length<limit;render();$('poll-status').textContent=`${rows.filter(p=>!p.archived).length} ${rows.filter(p=>!p.archived).length===1?'encuesta cargada':'encuestas cargadas'} · participación voluntaria`;}catch{if(v===listVersion)$('poll-status').textContent='No se pudieron cargar las encuestas. Pulsa Actualizar para reintentar.';}}
 async function open(p,resultsFirst=false){if(!p)return;current=p;ownVote=null;result=null;const v=++detailVersion;detail.showModal();$('poll-detail-body').innerHTML=`<h2 id="poll-detail-title">${esc(p.title)}</h2><p role="status">Cargando encuesta…</p>`;if(!user){draw(p,resultsFirst);return;}const uid=user.id;try{const [vote,stats]=await Promise.all([db.from('atlas_dev_poll_votes').select('choices,answer,answers').eq('poll_id',p.id).eq('user_id',uid).maybeSingle(),db.rpc('atlas_dev_survey_results',{p_poll_id:p.id})]);if(v!==detailVersion||uid!==user?.id)return;if(vote.error||stats.error)throw vote.error||stats.error;ownVote=vote.data;result=stats.data;draw(p,resultsFirst||!!ownVote);}catch{if(v===detailVersion){draw(p,resultsFirst);$('poll-detail-status').textContent='No se pudieron actualizar los resultados. Pulsa Actualizar resultados.';}}}
 function questionResult(q,i){const total=Number(q.total);return `<section class="survey-question-result"><span class="eyebrow">PREGUNTA ${i+1} · ${esc(pollTypes[q.kind])}</span><h3>${esc(q.title)}</h3><p class="muted">${total} ${total===1?'respuesta':'respuestas'}</p>${total===0?'<p>Todavía no hay respuestas.</p>':q.bars.map(b=>`<div class="poll-bar"><div><span>${esc(b.label)}</span><b>${percent(b.count,total)}% <small>(${b.count})</small></b></div><progress max="100" value="${percent(b.count,total)}" aria-label="${esc(b.label)}: ${b.count}"></progress></div>`).join('')}${q.kind==='multiple'?'<p class="muted">Porcentaje de participantes que eligió cada opción; puede sumar más de 100%.</p>':''}${q.kind==='text'?`<p class="muted">Últimas 100 respuestas, sin nombre de la cuenta.</p>${q.texts.map(t=>`<blockquote>${esc(t)}</blockquote>`).join('')}`:''}</section>`;}
 function resultsMarkup(p){if(!result)return '<p>Ingresa con Convergencia para consultar los resultados.</p>';const total=Number(result.total);return `<div class="poll-result-total"><strong>${total.toLocaleString('es-CL')}</strong> ${total===1?'participante':'participantes'}</div>${result.questions.map(questionResult).join('')}<h3>Participación en el tiempo</h3>${result.days.length?`<div class="poll-days">${result.days.map(d=>`<div><time>${esc(d.date)}</time><meter min="0" max="${Math.max(...result.days.map(d=>Number(d.count)),1)}" value="${d.count}">${d.count}</meter><b>${d.count}</b></div>`).join('')}</div>`:'<p class="muted">La evolución aparecerá al recibir respuestas.</p>'}`;}
 function ballotMarkup(p){return `<form id="poll-vote-form"><p class="muted">${questionsOf(p).length} pregunta(s). Responde todas y envía al finalizar.</p>${questionsOf(p).map((q,i)=>`<fieldset class="survey-question-vote"><legend>${i+1}. ${esc(q.title)}</legend><p class="muted">${esc(pollTypes[q.kind])}</p>${q.kind==='text'?`<textarea name="answer-${i}" required minlength="2" maxlength="1000" aria-label="Respuesta a la pregunta ${i+1}" placeholder="Comparte tu opinión sin datos personales"></textarea><p class="muted">Tu texto será visible para la comunidad sin mostrar tu nombre.</p>`:q.options.map((o,j)=>`<label class="poll-option"><input type="${q.kind==='multiple'?'checkbox':'radio'}" name="choice-${i}" value="${j}" ${q.kind!=='multiple'?'required':''}>${esc(o)}</label>`).join('')}</fieldset>`).join('')}<button class="primary" id="send-poll-vote">Enviar respuestas</button></form>`;}
 function savedMarkup(p){const answers=answersOf(ownVote);return `<p class="poll-success">✓ Tus respuestas están guardadas en tu cuenta.</p>${questionsOf(p).map((q,i)=>`<section class="survey-saved"><h3>${i+1}. ${esc(q.title)}</h3><p>${esc(q.kind==='text'?answers[i]?.answer||'':(answers[i]?.choices||[]).map(n=>q.options[n]).join(' · '))}</p></section>`).join('')}`;}
 function draw(p,showResults=false){
  const closed=pollClosed(p);$('poll-detail-body').innerHTML=`<span class="eyebrow">TENDENCIAS / ${esc(p.topic)}</span><h2 id="poll-detail-title">${esc(p.title)}</h2><p>${esc(p.description)}</p><div class="trends-tabs"><button id="poll-tab-vote" class="${!showResults?'active':''}">Participar</button><button id="poll-tab-results" class="${showResults?'active':''}">Resultados</button></div><section id="poll-vote-panel" ${showResults?'hidden':''}>${!user?'<p>Ingresa con tu cuenta de Convergencia para responder una vez y guardar tu participación.</p><button id="poll-login" class="primary">Ingresar con Convergencia</button>':ownVote?savedMarkup(p):closed?'<p>Esta encuesta está cerrada. Puedes consultar sus resultados.</p>':ballotMarkup(p)}</section><section id="poll-results-panel" ${!showResults?'hidden':''}>${resultsMarkup(p)}${!user?'<button id="poll-results-login">Ingresar con Convergencia</button>':''}</section><p id="poll-detail-status" role="status"></p><button id="poll-reload">↻ Actualizar resultados</button><details class="poll-method"><summary>Ficha técnica y método</summary><p>Consulta creada por un miembro de Convergencia. Participación voluntaria, sin muestreo probabilístico ni ponderación. No representa a toda la población.</p><dl><dt>Inicio</dt><dd>${esc(date(p.created_at))}</dd><dt>Cierre previsto</dt><dd>${esc(date(p.closes_at))}</dd><dt>Estado</dt><dd>${p.archived?'Archivada':closed?'Cerrada':'Abierta'}</dd><dt>Formato</dt><dd>${questionsOf(p).length>1?`${questionsOf(p).length} preguntas · formatos combinados`:esc(pollTypes[questionsOf(p)[0].kind])}</dd><dt>Control de participación</dt><dd>Una respuesta por cuenta; no equivale a una verificación de identidad personal.</dd></dl></details>${p.owner_id===user?.id?`<div class="poll-manage">${!closed?'<button data-manage-poll="close">Cerrar recepción de respuestas</button>':''}<button data-manage-poll="${p.archived?'restore':'archive'}">${p.archived?'Restaurar':'Archivar'} encuesta</button></div>`:''}`;
  function switchPanel(show){$('poll-vote-panel').hidden=show;$('poll-results-panel').hidden=!show;$('poll-tab-vote').classList.toggle('active',!show);$('poll-tab-results').classList.toggle('active',show);}$('poll-tab-vote').onclick=()=>switchPanel(false);$('poll-tab-results').onclick=()=>switchPanel(true);$('poll-login')?.addEventListener('click',()=>{detail.close();login();});$('poll-results-login')?.addEventListener('click',()=>{detail.close();login();});$('poll-reload').onclick=()=>open(p,true);
  $('poll-vote-form')?.addEventListener('submit',async e=>{e.preventDefault();const uid=user?.id;if(!uid)return;let answers;try{answers=surveyAnswers(p,new FormData(e.target));}catch(error){$('poll-detail-status').textContent=error.message;return;}$('send-poll-vote').disabled=true;try{const {error}=await db.rpc('atlas_dev_vote_survey',{p_poll_id:p.id,p_answers:answers});if(error)throw error;if(user?.id===uid)await open(p,true);}catch(e){$('poll-detail-status').textContent=e.message||'No se pudieron guardar tus respuestas.';$('send-poll-vote')?.removeAttribute('disabled');}});
  detail.querySelectorAll('[data-manage-poll]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const {error}=await db.rpc('atlas_dev_manage_poll',{p_poll_id:p.id,p_action:b.dataset.managePoll});if(error)throw error;detail.close();await load();}catch(e){$('poll-detail-status').textContent=e.message;b.disabled=false;}});
 }
 function auth(session){const next=session?.user||null;if(next?.id===user?.id)return;user=next;detailVersion++;detail.close();create.close();resetBuilder();load();}
 if(db){db.auth.getSession().then(({data})=>{auth(data.session);load();});db.auth.onAuthStateChange((_e,s)=>setTimeout(()=>auth(s),0));}else load();
 return {refresh:load};
}
